import java.io.*;
class FileAlpha
{
 String str[];
 int n;
 FileAlpha(int nn)
 { n = nn; str = new String[n]; }
 void readFile() throws Exception
 {
  BufferedReader br = new BufferedReader(new FileReader("Student.txt"));
  for(int i=0;i<n;i++)
   str[i] = br.readLine();
  br.close();
 }
 void alphabetic()
 {
  for(int i=0;i<n-1;i++)
   for(int j=i+1;j<n;j++)
    if(str[i].compareTo(str[j])>0)
    { String t=str[i]; str[i]=str[j]; str[j]=t; }
 }
 void show()
 { for(int i=0;i<n;i++) System.out.println(str[i]); }
 public static void main(String args[]) throws Exception
 {
  FileAlpha ob=new FileAlpha(50);
  ob.readFile(); ob.alphabetic(); ob.show();
 }
}

class SpyNumGen
{
 int start,end;
 SpyNumGen(int a,int b)
 { start=a; end=b; }
 int sum_digits(int n)
 { int s=0; while(n>0) { s+=n%10; n/=10; } return s; }
 int prod_digits(int n)
 { int p=1; while(n>0) { p*=n%10; n/=10; } return p; }
 void generate()
 {
  for(int i=start;i<=end;i++)
   if(sum_digits(i)==prod_digits(i))
    System.out.println(i);
 }
 public static void main(String args[])
 { SpyNumGen ob=new SpyNumGen(1,500); ob.generate(); }
}

import java.util.*;
class ColMin
{
 int mat[][]; int m;
 ColMin(int mm) { m=mm; mat=new int[m][m]; }
 void accept()
 { Scanner sc=new Scanner(System.in);
  for(int i=0;i<m;i++) for(int j=0;j<m;j++) mat[i][j]=sc.nextInt(); }
 void small_col(int n)
 { int min=mat[0][n]; int row=0;
  for(int i=1;i<m;i++) if(mat[i][n]<min) { min=mat[i][n]; row=i; }
  System.out.println("Smallest = "+min);
  System.out.println("Row = "+row+" Column = "+n); }
 void display()
 { for(int i=0;i<m;i++) { for(int j=0;j<m;j++) System.out.print(mat[i][j]+" "); System.out.println(); } }
 public static void main(String args[])
 { ColMin ob=new ColMin(3); ob.accept(); ob.display(); ob.small_col(0); }
}

